  "steps": [
    {
      "id": 1,
      "claim": "Article 38(1) of the Statute of the International Court of Justice lists treaties, international custom, and general principles of law as the sources the Court shall apply, without assigning ordinal priority or hierarchical ranking to them.",
      "evidence": "The text of Article 38(1) uses the conjunction 'and' to list these sources concurrently, lacking language such as 'first' or 'second' that would imply a vertical hierarchy.",
      "weight": 0.4,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "The standard doctrinal interpretation, supported by ICJ jurisprudence, is that these sources have equal status and no source type inherently supersedes another.",
      "evidence": "Scholarly consensus and cases like the North Sea Continental Shelf confirm that the sources are concurrent and not ranked by type.",
      "weight": 0.3,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "Conflicts between different formal sources are resolved by interpretive maxims such as lex specialis (specific over general) and lex posterior (later over earlier), rather than a fixed hierarchy of source types.",
      "evidence": "Standard international law doctrine and the Vienna Convention on the Law of Treaties (Art. 31) provide for resolution via interpretation and temporal/specificity rules, not source-type superiority.",
      "weight": 0.3,
      "depends_on": [2]
    }
  ],
  "considered": [
    {
      "answer": "B",
      "reason_rejected": "Treaties do not inherently supersede custom; a later custom or a peremptory norm (jus cogens) can override a treaty, and conflicts are resolved by lex posterior/specialis, not source type."
    },
    {
      "answer": "C",
      "reason_rejected": "Custom does not inherently supersede treaties; parties are bound by their specific treaty obligations unless modified or terminated according to general international law rules."
    },
    {
      "answer": "D",
      "reason_rejected": "General principles of law are generally considered subsidiary gap-fillers and do not hold a superior hierarchical position over specific treaties or established customs."
    }
  ]
